function(input, params) {
  var p = params || {};
  var sep = p.separator || 'space';
  var bitLen = p.binaryLength || 8;
  var separatorMap = { 'space': ' ', 'comma': ', ', 'none': '' };
  var separator = separatorMap[sep] != null ? separatorMap[sep] : ' ';
  var max = (1 << bitLen) - 1;
  var binaryStr = '';
  for (var i = 0; i < input.length; i++) {
    var code = input.charCodeAt(i);
    if (code > max) {
      throw new Error('字符「' + input[i] + '」超出 ' + bitLen + ' 位范围，请用更大的位数');
    }
    var bin = code.toString(2);
    while (bin.length < bitLen) bin = '0' + bin;
    binaryStr += bin;
  }
  var result = 'I think ';
  for (var i = 0; i < binaryStr.length; i++) {
    result += (binaryStr[i] === '0') ? 'that he thinks' : 'that she thinks';
    if (i < binaryStr.length - 1) result += separator;
  }
  result += ' me.';
  return result;
}

