function(input, params) {
  var p = params || {};
  var bitLen = p.binaryLength || 8;
  var clean = input.replace(/^I think\s*/, '').replace(/\s*me\.\s*$/, '');
  var binaryStr = '';
  var re = /that\s+(he|she)\s+thinks/g;
  var m;
  while ((m = re.exec(clean)) !== null) {
    binaryStr += (m[1] === 'she') ? '1' : '0';
  }
  var result = '';
  for (var i = 0; i + bitLen <= binaryStr.length; i += bitLen) {
    result += String.fromCharCode(parseInt(binaryStr.substr(i, bitLen), 2));
  }
  return result;
}
